<script setup lang="ts">
import { reactive, ref } from "vue"; import { ElMessage } from "element-plus"; import { faqGapApi } from "../api/ops"; import type { FaqCandidate, KnowledgeGap, PublishedFaq } from "../types";
const tab=ref("candidates");const windowDays=ref(30);const candidates=ref<FaqCandidate[]>([]);const published=ref<PublishedFaq[]>([]);const gaps=ref<KnowledgeGap[]>([]);const editFaq=ref<PublishedFaq|null>(null);const convertGap=ref<KnowledgeGap|null>(null);const faqForm=reactive({question:"",answer:""});const gapForm=reactive({title:"",category_id:""});
async function load(){const [c,p,g]=await Promise.all([faqGapApi.candidates(),faqGapApi.published(),faqGapApi.gaps()]);candidates.value=c.items;published.value=p.items;gaps.value=g.items}void load();
async function mine(){await faqGapApi.mineFaq(windowDays.value);ElMessage.success("FAQ 挖掘完成");await load()}
async function detect(){await faqGapApi.detectGaps(windowDays.value);ElMessage.success("知识缺口检测完成");await load()}
async function review(row:FaqCandidate,decision:string){await faqGapApi.reviewFaq({candidate_id:row.candidate_id,question:row.question,decision,reason:decision==="reject"?"人工审核驳回":""});await load()}
function openFaq(row:PublishedFaq){editFaq.value=row;Object.assign(faqForm,{question:row.question,answer:row.answer})}
async function saveFaq(){if(editFaq.value)await faqGapApi.updatePublished(editFaq.value.faq_id,faqForm);editFaq.value=null;await load()}
function openGap(row:KnowledgeGap){convertGap.value=row;Object.assign(gapForm,{title:row.question,category_id:row.suggested_category})}
async function saveGap(){if(convertGap.value)await faqGapApi.convertGap(convertGap.value.gap_id,gapForm);convertGap.value=null;await load()}
</script><template><el-card class="page-card"><template #header><div class="card-header"><span>沉淀运营</span><el-space><el-input-number v-model="windowDays" :min="1" :max="365"/><el-button @click="mine">挖掘 FAQ</el-button><el-button @click="detect">检测知识缺口</el-button></el-space></div></template><el-tabs v-model="tab"><el-tab-pane label="FAQ 候选" name="candidates"><el-table :data="candidates"><el-table-column prop="question" label="标准问题" min-width="220"/><el-table-column prop="answer" label="推荐答案" min-width="260"/><el-table-column prop="frequency" label="频次" width="80"/><el-table-column prop="confidence" label="置信度" width="90"/><el-table-column prop="status" label="状态" width="110"/><el-table-column label="操作" width="150"><template #default="s"><el-button v-if="['candidate','pending_review'].includes(s.row.status)" link @click="review(s.row,'approve')">发布</el-button><el-button v-if="['candidate','pending_review'].includes(s.row.status)" link type="danger" @click="review(s.row,'reject')">驳回</el-button></template></el-table-column></el-table></el-tab-pane><el-tab-pane label="已发布 FAQ" name="published"><el-table :data="published"><el-table-column prop="question" label="标准问题" min-width="220"/><el-table-column prop="answer" label="答案" min-width="280"/><el-table-column prop="status" label="状态" width="100"/><el-table-column prop="updated_at" label="更新时间" width="190"/><el-table-column label="操作" width="150"><template #default="s"><el-button link @click="openFaq(s.row)">编辑</el-button><el-button link @click="faqGapApi.setPublishedStatus(s.row.faq_id,s.row.status==='published'?'disabled':'published').then(load)">{{s.row.status==='published'?'停用':'启用'}}</el-button></template></el-table-column></el-table></el-tab-pane><el-tab-pane label="知识缺口" name="gaps"><el-table :data="gaps"><el-table-column prop="question" label="代表问题" min-width="220"/><el-table-column prop="gap_type" label="类型" width="130"/><el-table-column prop="frequency" label="频次" width="80"/><el-table-column prop="suggested_category" label="建议分类" width="130"/><el-table-column prop="status" label="状态" width="110"/><el-table-column label="操作" width="180"><template #default="s"><el-button v-if="s.row.status==='pending'" link @click="openGap(s.row)">转建草稿</el-button><el-button v-if="s.row.status==='pending'" link type="danger" @click="faqGapApi.resolveGap(s.row.gap_id,{decision:'ignore',reason:'运营手动忽略'}).then(load)">忽略</el-button></template></el-table-column></el-table></el-tab-pane></el-tabs><el-dialog :model-value="Boolean(editFaq)" title="编辑已发布 FAQ" @close="editFaq=null"><el-form label-position="top"><el-form-item label="标准问题"><el-input v-model="faqForm.question"/></el-form-item><el-form-item label="标准答案"><el-input v-model="faqForm.answer" type="textarea" :rows="5"/></el-form-item></el-form><template #footer><el-button @click="editFaq=null">取消</el-button><el-button type="primary" @click="saveFaq">保存</el-button></template></el-dialog><el-dialog :model-value="Boolean(convertGap)" title="转建知识补充草稿" @close="convertGap=null"><el-form label-position="top"><el-form-item label="知识标题"><el-input v-model="gapForm.title"/></el-form-item><el-form-item label="分类"><el-input v-model="gapForm.category_id"/></el-form-item></el-form><template #footer><el-button @click="convertGap=null">取消</el-button><el-button type="primary" @click="saveGap">创建</el-button></template></el-dialog></el-card></template>
